// =====================================================================
// EVERWAKE CLINIC — Outbox · NODE: One Item Per Message
// The claimed batch → one item per message, each with the clinic's own
// WhatsApp connection. Reminders, delay notices, staff replies, alerts to
// a doctor's own number… Nothing claimed → nothing to do.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
// an Egyptian number as people write it: 201001234567 → 01001234567
const localPhone = (p) => str(p).replace(/^\+?20(1\d{9})$/, '0$1');
const batch = arr(parseJson(obj($input.first().json).r, []));
return batch.map(m => {
  const ch = obj(m.channel);
  const meta = obj(m.meta);
  return {
    json: {
      id: m.id, tenant_id: m.tenant_id, wa_id: m.wa_id, to: m.to, purpose: m.purpose,
      kind: ['document', 'image', 'location'].includes(m.kind) ? m.kind : 'text',
      text: str(m.body), media_url: m.media_url || null, mime: m.media_mime || (m.kind === 'document' ? 'application/pdf' : 'image/jpeg'),
      file_name: m.file_name || (m.kind === 'document' ? 'file.pdf' : 'photo.jpg'),
      lat: meta.lat ?? null, lng: meta.lng ?? null, place: str(meta.place), address: str(meta.address),
      base_url: str(ch.base_url), instance: str(ch.instance), api_key: str(ch.api_key),
      delay_ms: Math.min(1500, Math.max(400, Math.round(str(m.body).length * 8)))
    }
  };
});

// =====================================================================
// EVERWAKE CLINIC — Outbox · NODE: Record Result
// Evolution's answer → sent, or a retry (up to 3 attempts), or failed
// with the reason the dashboard shows next to the message.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
// an Egyptian number as people write it: 201001234567 → 01001234567
const localPhone = (p) => str(p).replace(/^\+?20(1\d{9})$/, '0$1');
const item = $('Send Loop').first().json;
const r = $input.first().json || {};
const body = obj(r.body && typeof r.body === 'object' ? r.body : r);
const id = str(obj(body.key).id) || null;
const ok = !!id && !r.error;
let error = null;
if (!ok) {
  const detail = obj(body.response).message;
  error = Array.isArray(detail) && detail.some(d => d && d.exists === false)
    ? 'This number is not on WhatsApp.'
    : str(obj(r.error).message || r.error || (detail && JSON.stringify(detail)) || body.message || 'WhatsApp (Evolution) did not confirm the message.');
}
return [{ json: { b64_result: b64({ id: item.id, ok, external_id: id, error: error ? error.slice(0, 300) : null }) } }];
